## Task: Enforce Response Validation

### Context
- Empty response tools: {{previousTaskOutput['test-for-empty-responses']}}
- Misleading tools: {{previousTaskOutput['verify-claims-vs-reality']}}

### Objective
Add validation layers to detect and handle empty/invalid responses.

### Implementation Strategy

```typescript
// In repos/metabob-opencode/packages/opencode/src/tools/metabob-tools.ts

import { z } from "zod";

// Define response schemas with validation
const SearchIssuesResponseSchema = z.object({
  results: z.array(z.object({
    id: z.string(),
    severity: z.enum(["HIGH", "MEDIUM", "LOW"]),
    description: z.string().min(1),
    file_path: z.string(),
    line: z.number(),
  })).min(1, "Search returned no results - external API may be unavailable"),
  total: z.number(),
});

const ChangeImpactResponseSchema = z.object({
  dependencies: z.array(z.string()),
  dependents: z.array(z.string()),
  risk_score: z.number().min(0).max(1),
}).refine(
  (data) => data.dependencies.length > 0 || data.dependents.length > 0,
  "Change impact analysis returned no dependencies - CPG may not be initialized"
);

// Wrap tool calls with validation
export async function metabob_search_codebase_issues(
  args: { query: string; limit: number }
): Promise<SearchIssuesResponse> {
  const response = await mcpClient.callTool("metabob_search_codebase_issues", args);

  try {
    return SearchIssuesResponseSchema.parse(response);
  } catch (error) {
    // Log validation failure
    logger.warn("Metabob search returned invalid response", {
      error: error.message,
      query: args.query,
      response_preview: JSON.stringify(response).substring(0, 200),
    });

    // Return graceful fallback
    return {
      results: [],
      total: 0,
      error: "External API unavailable or returned invalid data",
      fallback: true,
    };
  }
}

export async function metabob_analyze_change_impact(
  args: { file_path: string; component_name?: string }
): Promise<ChangeImpactResponse> {
  const response = await mcpClient.callTool("metabob_analyze_change_impact", args);

  try {
    return ChangeImpactResponseSchema.parse(response);
  } catch (error) {
    logger.warn("Metabob change impact returned invalid response", {
      error: error.message,
      file_path: args.file_path,
      component_name: args.component_name,
    });

    // Return graceful fallback
    return {
      dependencies: [],
      dependents: [],
      risk_score: 0.5, // Unknown risk
      error: "CPG not initialized or component not found",
      fallback: true,
    };
  }
}
```

### Add Integration Tests

```typescript
// In repos/metabob-opencode/packages/opencode/tests/metabob-validation.test.ts

import { describe, it, expect } from "bun:test";
import { metabob_search_codebase_issues } from "../src/tools/metabob-tools";

describe("Metabob Response Validation", () => {
  it("should handle empty search results gracefully", async () => {
    const result = await metabob_search_codebase_issues({
      query: "nonexistent_pattern_xyz123",
      limit: 10,
    });

    expect(result).toBeDefined();
    expect(result.results).toBeArray();

    if (result.fallback) {
      expect(result.error).toContain("unavailable");
    }
  });

  it("should handle CPG not initialized", async () => {
    const result = await metabob_analyze_change_impact({
      file_path: "nonexistent/file.ts",
    });

    expect(result).toBeDefined();
    expect(result.dependencies).toBeArray();
    expect(result.dependents).toBeArray();

    if (result.fallback) {
      expect(result.error).toContain("not initialized");
    }
  });
});
```

### Success Criteria
- Response schemas defined with Zod
- Validation wrappers added to all tools
- Graceful fallbacks for empty responses
- Integration tests added

